#!/usr/bin/env node
// Flattens docker-compose.full.yml (which `include`s docker-compose.yml) into
// docker-compose.coolify.yml for platforms that only read a single compose file.
// Run with --check to fail when the generated file is out of date.
import { readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const corePath = path.join(root, "docker-compose.yml");
const fullPath = path.join(root, "docker-compose.full.yml");
const outputPath = path.join(root, "docker-compose.coolify.yml");

const header = [
  "# GENERATED by scripts/generate-coolify-compose.mjs. Do not edit by hand:",
  "# change docker-compose.yml or docker-compose.full.yml, then run",
  "#   node scripts/generate-coolify-compose.mjs",
  "# The full stack (core + Listmonk email) as one file, for Coolify and other",
  "# platforms that don't support Compose `include`.",
  ""
].join("\n");

function extractServiceEntries(fullText) {
  const includeMatch = fullText.match(/^include:\n((?: {2}- .+\n)+)/m);
  const includes = includeMatch ? includeMatch[1].trim().split("\n").map((line) => line.replace(/^- /, "").trim()) : [];
  if (includes.length !== 1 || includes[0] !== "docker-compose.yml") {
    throw new Error("docker-compose.full.yml must include exactly docker-compose.yml.");
  }

  const servicesMatch = fullText.match(/^services:\n([\s\S]*)$/m);
  if (!servicesMatch) {
    throw new Error("docker-compose.full.yml has no services section.");
  }
  return servicesMatch[1];
}

function buildCoolifyCompose() {
  const coreText = readFileSync(corePath, "utf8");
  if (!coreText.startsWith("services:\n")) {
    throw new Error("docker-compose.yml must start with its services section.");
  }
  if (/^(?!services:)[A-Za-z_]/m.test(coreText)) {
    throw new Error("docker-compose.yml may only have a services section; update this generator to merge other top-level keys.");
  }
  return `${header}${coreText.trimEnd()}\n${extractServiceEntries(readFileSync(fullPath, "utf8")).trimEnd()}\n`;
}

const generated = buildCoolifyCompose();

if (process.argv.includes("--check")) {
  let current = "";
  try {
    current = readFileSync(outputPath, "utf8");
  } catch {
    // Missing file counts as out of date.
  }
  if (current !== generated) {
    console.error("docker-compose.coolify.yml is out of date. Run: node scripts/generate-coolify-compose.mjs");
    process.exit(1);
  }
  console.log("docker-compose.coolify.yml is up to date.");
} else {
  writeFileSync(outputPath, generated);
  console.log("Wrote docker-compose.coolify.yml.");
}
